#include <stdio.h>
#include <string.h>

struct Student {
    const char *name;
    int grade;
};

int main(void) {
    int n;
    scanf("%d", &n);
    struct Student group[50];
    char buffer[32];
    int total = 0;
    for (int i = 0; i < n; i++) {
        scanf("%31s %d", buffer, &group[i].grade);
        group[i].name = buffer;
        total += group[i].grade;
    }
    for (int i = 0; i < n; i++) {
        if (group[i].grade * n >= total) {
            printf("%s %d\n", group[i].name, group[i].grade);
        }
    }
    return 0;
}

