#include <stdio.h>
#include <string.h>

struct Product {
    char name[24];
    int price;
};

int main(void) {
    int n;
    scanf("%d", &n);
    struct Product items[50];
    for (int i = 0; i < n; i++) {
        scanf("%23s %d", items[i].name, &items[i].price);
    }
    int chosen = 0;
    for (int i = 1; i < n; i++) {
        if (items[i].price > items[chosen].price) {
            chosen = i;
        }
    }
    int d;
    scanf("%d", &d);
    for (int k = 0; k < d; k++) {
        int index;
        scanf("%d", &index);
        memmove(&items[index], &items[index + 1], (size_t)(n - index - 1) * sizeof items[0]);
        n--;
        if (index < chosen) {
            chosen--;
        }
    }
    printf("%s %d %d\n", items[chosen].name, items[chosen].price, n);
    return 0;
}

