const char *format_price(int cents) {
    char text[32];
    snprintf(text, sizeof text, "%d.%02d руб.", cents / 100, cents % 100);
    return text;
}

int main(void) {
    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        int cents;
        scanf("%d", &cents);
        const char *text = format_price(cents);
        printf("%s\n", text);
    }
    return 0;
}

