#include <stdio.h>
#include <string.h>

#define CAPACITY 100

struct Slot {
    int value;
    unsigned generation;
    int used;
};

static struct Slot slots[CAPACITY];

int valid(int i, unsigned g) {
    return i >= 0 && i < CAPACITY && slots[i].used && slots[i].generation == g;
}

int main(void) {
    char cmd[8];
    while (scanf("%7s", cmd) == 1) {
        if (strcmp(cmd, "add") == 0) {
            int x;
            scanf("%d", &x);
            int i = 0;
            while (i < CAPACITY && slots[i].used) {
                i++;
            }
            if (i == CAPACITY) {
                printf("full\n");
            } else {
                slots[i].value = x;
                slots[i].used = 1;
                printf("%d:%u\n", i, slots[i].generation);
            }
        } else {
            int i;
            unsigned g;
            scanf("%d %u", &i, &g);
            if (!valid(i, g)) {
                printf("invalid\n");
            } else if (strcmp(cmd, "get") == 0) {
                printf("%d\n", slots[i].value);
            } else {
                slots[i].used = 0;
                slots[i].generation++;
                printf("ok\n");
            }
        }
    }
    return 0;
}

